	for _, tc := range tests {
		got := CoreLineIntersectCoreLine(tc.line1, tc.line2)
		if tc.expect == nil {
			if got != nil { t.Errorf("expected nil, got %v", *got) }
		} else {
			if got == nil { t.Error("expected non-nil") }
			if math.Abs(got.X-tc.expect.X)>0.001||math.Abs(got.Y-tc.expect.Y)>0.001 {
				t.Errorf("pt: got (%.6f,%.6f), want (%.6f,%.6f)", got.X, got.Y, tc.expect.X, tc.expect.Y)
			}
		}
	}
