func TestSubpathLineOriginIsZero(t *testing.T) {
	l := core.NewLine(core.PdfPoint{}, core.PdfPoint{})
	if l.From.X!=0||l.From.Y!=0||l.To.X!=0||l.To.Y!=0 { t.Error("expected zero line") }
}

func TestSubpathLineParallelTo(t *testing.T) {
	v1 := core.NewLine(core.NewPdfPoint(10, 7.5), core.NewPdfPoint(10, 15))
	v2 := core.NewLine(core.NewPdfPoint(200, 0), core.NewPdfPoint(200, 551.5467))
	h1 := core.NewLine(core.NewPdfPoint(10, 7.5), core.NewPdfPoint(26.3, 7.5))
	h2 := core.NewLine(core.NewPdfPoint(27, 57), core.NewPdfPoint(200.9999872, 57))
	o1 := core.NewLine(core.NewPdfPoint(10, 7.5), core.NewPdfPoint(26.3, 12))
	o2 := core.NewLine(core.NewPdfPoint(60, 28.8036809815951), core.NewPdfPoint(40, 23.2822085889571))

	tests := []struct{a,b *core.Line;expect bool}{
		{v1,v2,true},{v2,v1,true},
		{o1,v2,false},{v2,o1,false},
		{o1,v1,false},{v1,o1,false},
		{h1,h2,true},{h2,h1,true},
		{o1,h1,false},{h1,o1,false},
		{o1,h2,false},{h2,o1,false},
		{v1,h2,false},{h2,v1,false},
		{v2,h2,false},{h2,v2,false},
		{o1,o2,true},{o2,o1,true},
	}
	for _, tc := range tests {
		got := CoreLineParallelTo(tc.a, tc.b)
		if got != tc.expect { t.Errorf("got %t, want %t", got, tc.expect) }
	}
}
